getRefreshToken() {
  for (const login of Services.logins.findLogins(
    this._loginOrigin,
    null,
    ""
  )) {
    if (login.username != this._username) {
      continue;
    }

    if (scopeSet(login.httpRealm).isSupersetOf(this._requiredScopes)) {
      this._scope = login.httpRealm;
      return login.password;
    }
  }
